begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
do $test$
declare
 a uuid:=gen_random_uuid();a2 uuid:=gen_random_uuid();c uuid:=gen_random_uuid();c2 uuid:=gen_random_uuid();w uuid:=gen_random_uuid();w2 uuid:=gen_random_uuid();w3 uuid:=gen_random_uuid();
 r uuid:=gen_random_uuid();e uuid:=gen_random_uuid();j uuid:=gen_random_uuid();t uuid:=gen_random_uuid();event uuid:=gen_random_uuid();
 chat public.conversations%rowtype;team public.conversations%rowtype;wc public.conversations%rowtype;m public.messages%rowtype;m2 public.messages%rowtype;
 n uuid;other_n uuid;last_n uuid;before_count bigint;snapshot jsonb;
begin
 insert into auth.users(id,email,raw_user_meta_data) select x,x::text||'@example.invalid','{}'::jsonb from unnest(array[a,a2,c,c2,w,w2,w3]) x;
 update public.profiles set role='admin' where id=any(array[a,a2]);
 update public.profiles set role='worker' where id=any(array[w,w2,w3]);
 insert into public.trucks(id,name) values(t,'Notification truck');
 insert into public.move_requests(id,customer_id,pickup,destination,requested_date,property_type,move_size,items,access_details)
 values(r,c,'10 Test Lane','20 Test Road',current_date+20,'House','Studio','Boxes','Ground floor');
 insert into public.estimates(id,request_id,created_by,status,terms,published_at,total_cents) values(e,r,a,'awaiting','Test',now(),50000);
 if exists(select 1 from public.notifications where recipient_id=any(array[a,a2,c,c2,w,w2,w3])) then raise exception 'Historical/empty records generated alerts';end if;
 insert into public.estimate_events(id,estimate_id,actor_id,previous_status,new_status) values(event,e,a,'draft','awaiting');
 if (select count(*) from public.notifications where event_id=event)<>1 then raise exception 'Publication recipients incorrect';end if;
 select id into n from public.notifications where event_id=event and recipient_id=c;
 set local role authenticated;perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 snapshot:=public.notification_snapshot();
 if (snapshot->>'unread')::int<>1 or snapshot->'items'->0->>'target_id'<>e::text then raise exception 'Customer publication target incorrect';end if;
 begin update public.notifications set recipient_id=c2 where id=n;raise exception 'Direct alert editing allowed';exception when insufficient_privilege then null;end;
 begin insert into public.notifications(recipient_id,kind,event_id,estimate_id) values(c,'estimate-published',gen_random_uuid(),e);raise exception 'Forged alert allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c2,'role','authenticated')::text,true);
 if exists(select 1 from public.notifications) then raise exception 'Unrelated customer read alerts';end if;
 begin perform public.mark_notifications(n);raise exception 'Other customer marked alert';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 chat:=public.open_conversation('customer-support',c);
 m:=public.send_message(chat.id,'Private customer text must not appear in alert',gen_random_uuid());
 perform public.send_message(chat.id,m.body,m.request_id);
 reset role;
 if (select count(*) from public.notifications where event_id=m.id and recipient_id=any(array[a,a2]))<>2 then raise exception 'Multi-admin or duplicate retry failed';end if;
 if exists(select 1 from public.notifications where event_id=m.id and recipient_id=any(array[c,c2,w,w2,w3])) then raise exception 'Wrong support recipients';end if;
 select id into other_n from public.notifications where event_id=m.id and recipient_id=a2;
 set local role authenticated;perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 select id into last_n from public.notifications where event_id=m.id;
 perform public.mark_notifications(last_n);
 if exists(select 1 from public.notifications where id=other_n) then raise exception 'Admin saw another admins notification';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a2,'role','authenticated')::text,true);
 if not exists(select 1 from public.notifications where id=other_n and read_at is null) then raise exception 'Read cleared another admin';end if;
 m2:=public.send_message(chat.id,'Company reply',gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 select id into last_n from public.notifications where event_id=m2.id;
 -- Mark-all uses a stored snapshot cutoff, never a client timestamp.
 perform public.mark_notifications(null,last_n);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 m:=public.send_message(chat.id,'Later reply',gen_random_uuid());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 perform public.mark_notifications(null,last_n);
 if not exists(select 1 from public.notifications where event_id=m.id and read_at is null) then raise exception 'Mark-all swallowed later alert';end if;
 perform public.mark_conversation_read(chat.id,m2.id);
 if not exists(select 1 from public.notifications where event_id=m.id and read_at is null) then raise exception 'Conversation cutoff swallowed later alert';end if;
 perform public.mark_conversation_read(chat.id,m.id);
 if exists(select 1 from public.notifications where conversation_id=chat.id and read_at is null) then raise exception 'Conversation read did not clear alerts';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',w,'role','authenticated')::text,true);
 wc:=public.open_conversation('worker-support',w);m:=public.send_message(wc.id,'Worker support',gen_random_uuid());
 reset role;
 if exists(select 1 from public.notifications where event_id=m.id and recipient_id=any(array[c,c2,w,w2,w3])) then raise exception 'Worker support mixed with customer support';end if;
 update public.estimates set status='accepted',decided_at=now() where id=e;
 insert into public.jobs(id,request_id,estimate_id,scheduled_date,start_time,end_time,arrival_start,arrival_end,truck_id)
 values(j,r,e,current_date+20,'09:00','12:00','09:00','10:00',t);
 insert into public.job_workers(job_id,worker_id) values(j,w),(j,w2);
 event:=gen_random_uuid();insert into public.job_events(id,job_id,actor_id,action,details) values(event,j,a,'scheduled','{}');
 if (select count(*) from public.notifications where event_id=event)<>3 then raise exception 'Schedule did not use final assigned crew';end if;
 set local role authenticated;perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);
 snapshot:=public.notification_snapshot();
 if not exists(select 1 from jsonb_array_elements(snapshot->'items') x where x->>'kind'='job-scheduled' and x->>'target_kind'='move' and x->>'target_id'=r::text) then raise exception 'Customer appointment target incorrect';end if;
 team:=public.open_conversation('move-team',j);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',w,'role','authenticated')::text,true);
 m:=public.send_message(team.id,'Team message',gen_random_uuid());
 if exists(select 1 from public.notifications where event_id=m.id) then raise exception 'Sender got own message alert';end if;
 reset role;
 if (select count(*) from public.notifications where event_id=m.id and recipient_id=any(array[c,w2,a,a2]))<>4 then raise exception 'Team recipients incorrect';end if;
 if exists(select 1 from public.notifications where event_id=m.id and recipient_id=any(array[c2,w,w3])) then raise exception 'Unrelated team recipient';end if;
 select id into last_n from public.notifications where recipient_id=w2 and event_id=m.id;
 delete from public.job_workers where job_id=j and worker_id=w2;
 insert into public.job_workers(job_id,worker_id) values(j,w3);
 event:=gen_random_uuid();insert into public.job_events(id,job_id,actor_id,action,details) values(event,j,a,'rescheduled','{}');
 if not exists(select 1 from public.notifications where event_id=event and recipient_id=w3) or exists(select 1 from public.notifications where event_id=event and recipient_id=w2) then raise exception 'Reassignment recipients incorrect';end if;
 set local role authenticated;perform set_config('request.jwt.claims',jsonb_build_object('sub',w2,'role','authenticated')::text,true);
 if exists(select 1 from public.notifications where id=last_n or job_id=j or conversation_id=team.id) then raise exception 'Removed worker kept alert access';end if;
 begin perform public.mark_notifications(last_n);raise exception 'Removed worker marked alert';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',w3,'role','authenticated')::text,true);
 if exists(select 1 from public.notifications where event_id=m.id) then raise exception 'New worker got retrospective alert';end if;
 reset role;update public.jobs set status='completed' where id=j;
 set local role authenticated;perform set_config('request.jwt.claims',jsonb_build_object('sub',w,'role','authenticated')::text,true);
 if not exists(select 1 from public.notifications where job_id=j) then raise exception 'Final worker lost completed history';end if;
 begin perform public.send_message(team.id,'Closed',gen_random_uuid());raise exception 'Completed chat reopened';exception when invalid_parameter_value then null;end;
 reset role;update public.profiles set active=false where id=w;
 set local role authenticated;perform set_config('request.jwt.claims',jsonb_build_object('sub',w,'role','authenticated')::text,true);
 if exists(select 1 from public.notifications) then raise exception 'Inactive account read alerts';end if;
 begin perform public.notification_snapshot();raise exception 'Inactive snapshot allowed';exception when insufficient_privilege then null;end;
 set local role anon;
 begin perform public.notification_snapshot();raise exception 'Anonymous snapshot allowed';exception when insufficient_privilege then null;end;
 begin perform count(*) from public.notifications;raise exception 'Anonymous alerts allowed';exception when insufficient_privilege then null;end;
end $test$;
select pass('Notification recipients, admin isolation, deduplication, read cutoffs, assignment and active access');
select * from finish();
rollback;
